    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                # The visible pattern is invariant under square-grid dihedral symmetries.
                candidates = {
                    grid[r][w - 1 - c],
                    grid[h - 1 - r][c],
                    grid[h - 1 - r][w - 1 - c],
                    grid[c][r],
                    grid[w - 1 - c][h - 1 - r],
                    grid[c][h - 1 - r],
                    grid[w - 1 - c][r],
                }
                candidates.discard(2)
                if len(candidates) != 1:
                    raise ValueError(f"cannot uniquely infer masked cell {(r, c)}: {candidates}")
                out[r][c] = candidates.pop()
